def solve(trials):
    for t in trials:
        if type(t['success']) is not bool or any(type(t[k]) is not int or t[k]<0 for k in ('steps','violations')):
            raise ValueError('trial')
    n=len(trials)
    return dict(success_rate=sum(t['success'] for t in trials)/n if n else None,
        safe_success_rate=sum(t['success'] and t['violations']==0 for t in trials)/n if n else None,
        mean_steps=sum(t['steps'] for t in trials)/n if n else None)

